"""NumPy-only copy of the V0.2 preprocessing functions generated by prepare.py."""
import numpy as np

FRAME_SHAPE = (128, 54)

def valid_depth_mask(depth):
    return np.isfinite(depth) & (depth > 0)

def preprocess(frame):
    frame = np.asarray(frame, dtype=np.float32)
    if frame.shape != FRAME_SHAPE:
        raise ValueError(f"Expected depth frame {FRAME_SHAPE}, got {frame.shape}")
    valid = valid_depth_mask(frame)
    normalized = np.zeros(FRAME_SHAPE, dtype=np.float32)
    if valid.any():
        depth = frame[valid]
        baseline = np.percentile(depth, 90, method="linear")
        normalized[valid] = np.clip(baseline - depth, 0, 600) / 600
    return normalized[None, None]
